// src/pages/AdvancedDashboardPage.jsx - Perbaikan
import React, { useState, useEffect, useCallback } from 'react';
import { Container, Row, Col, Card, Button, Table } from 'react-bootstrap';
import { 
  FaChartBar, FaFilter, FaDownload, FaSync, 
  FaCalendarAlt, FaUser, FaBuilding, FaMoneyBillWave,
  FaSearch, FaFileExport, FaChartLine, FaDatabase
} from 'react-icons/fa';

// HAPUS import chart.js jika tidak digunakan:
// import { Chart, BarElement, CategoryScale, LinearScale, Tooltip, Legend } from 'chart.js';
// import { Bar, Pie } from 'react-chartjs-2';

// Atau install dan gunakan dengan benar:
// Jika ingin menggunakan chart.js, install dan konfigurasi dengan benar

const AdvancedDashboardPage = () => {
  const [loading, setLoading] = useState(true);
  const [dashboardData, setDashboardData] = useState(null);
  const [timeRange, setTimeRange] = useState('month');

  const loadDashboardData = useCallback(async () => {
    try {
      setLoading(true);
      
      // Mock data
      const mockData = {
        summary: {
          totalSearches: 245,
          vendorsTracked: 156,
          packagesFound: 892,
          exportCount: 47,
          favoriteLpse: 'Kementerian PU'
        },
        searchesByType: {
          vendor: 120,
          package: 89,
          sbu: 36
        },
        topSearches: [
          { query: 'Adhi Karya', count: 45, type: 'vendor' },
          { query: 'Waskita Karya', count: 32, type: 'vendor' },
          { query: 'Jalan Tol', count: 28, type: 'package' },
          { query: 'Gedung Perkantoran', count: 24, type: 'package' },
          { query: 'PT PP', count: 19, type: 'vendor' }
        ],
        recentActivity: [
          { 
            page_url: '/vendor', 
            search_type: 'vendor', 
            search_query: 'PT Adhi Karya', 
            timestamp: new Date().toISOString() 
          },
          { 
            page_url: '/package', 
            search_type: 'package', 
            search_query: 'Jalan Tol', 
            timestamp: new Date(Date.now() - 1800000).toISOString() 
          },
          { 
            page_url: '/sbu', 
            search_type: 'sbu', 
            search_query: 'WIKA', 
            timestamp: new Date(Date.now() - 3600000).toISOString() 
          }
        ],
        monthlyTrends: [
          { month: 'Jan', searches: 45, exports: 12 },
          { month: 'Feb', searches: 52, exports: 15 },
          { month: 'Mar', searches: 49, exports: 10 },
          { month: 'Apr', searches: 62, exports: 18 },
          { month: 'May', searches: 55, exports: 16 },
          { month: 'Jun', searches: 68, exports: 22 }
        ]
      };

      setTimeout(() => {
        setDashboardData(mockData);
        setLoading(false);
      }, 1500);

    } catch (error) {
      console.error('Error loading dashboard:', error);
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadDashboardData();
  }, [loadDashboardData]);

  if (loading) {
    return (
      <Container className="py-5">
        <div className="text-center py-5">
          <div className="spinner-border text-primary" role="status">
            <span className="visually-hidden">Loading...</span>
          </div>
          <p className="mt-3">Memuat dashboard analytics...</p>
        </div>
      </Container>
    );
  }

  return (
    <Container className="py-4">
      <div className="d-flex justify-content-between align-items-center mb-4">
        <div>
          <h1 className="h2 mb-2">
            <FaChartBar className="me-2 text-primary" />
            Advanced Dashboard
          </h1>
          <p className="text-muted mb-0">
            Analytics lengkap dan insights mendalam
          </p>
        </div>
        <div className="d-flex gap-2">
          <Button variant="outline-primary">
            <FaFilter className="me-2" /> Filter
          </Button>
          <Button variant="outline-success">
            <FaDownload className="me-2" /> Export
          </Button>
          <Button variant="primary" onClick={loadDashboardData}>
            <FaSync className="me-2" /> Refresh
          </Button>
        </div>
      </div>

      {/* Summary Cards */}
      <Row className="g-4 mb-4">
        <Col md={3} sm={6}>
          <Card className="dashboard-card">
            <Card.Body>
              <div className="d-flex justify-content-between align-items-center">
                <div>
                  <h6 className="text-uppercase text-muted mb-2">
                    <FaSearch className="me-1" /> Total Pencarian
                  </h6>
                  <h2 className="mb-0">{dashboardData?.summary?.totalSearches || 0}</h2>
                </div>
                <div className="icon-circle bg-primary">
                  <FaSearch />
                </div>
              </div>
            </Card.Body>
          </Card>
        </Col>

        <Col md={3} sm={6}>
          <Card className="dashboard-card">
            <Card.Body>
              <div className="d-flex justify-content-between align-items-center">
                <div>
                  <h6 className="text-uppercase text-muted mb-2">
                    <FaBuilding className="me-1" /> Vendor Tracked
                  </h6>
                  <h2 className="mb-0">{dashboardData?.summary?.vendorsTracked || 0}</h2>
                </div>
                <div className="icon-circle bg-success">
                  <FaBuilding />
                </div>
              </div>
            </Card.Body>
          </Card>
        </Col>

        <Col md={3} sm={6}>
          <Card className="dashboard-card">
            <Card.Body>
              <div className="d-flex justify-content-between align-items-center">
                <div>
                  <h6 className="text-uppercase text-muted mb-2">
                    <FaDatabase className="me-1" /> Paket Ditemukan
                  </h6>
                  <h2 className="mb-0">{dashboardData?.summary?.packagesFound || 0}</h2>
                </div>
                <div className="icon-circle bg-info">
                  <FaDatabase />
                </div>
              </div>
            </Card.Body>
          </Card>
        </Col>

        <Col md={3} sm={6}>
          <Card className="dashboard-card">
            <Card.Body>
              <div className="d-flex justify-content-between align-items-center">
                <div>
                  <h6 className="text-uppercase text-muted mb-2">
                    <FaFileExport className="me-1" /> Total Export
                  </h6>
                  <h2 className="mb-0">{dashboardData?.summary?.exportCount || 0}</h2>
                </div>
                <div className="icon-circle bg-warning">
                  <FaFileExport />
                </div>
              </div>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      <Row className="g-4">
        {/* Top Searches */}
        <Col lg={6}>
          <Card className="h-100">
            <Card.Header className="bg-primary text-white">
              <FaChartLine className="me-2" /> Top Pencarian
            </Card.Header>
            <Card.Body>
              <Table hover responsive>
                <thead>
                  <tr>
                    <th>#</th>
                    <th>Query</th>
                    <th>Jumlah</th>
                    <th>Tipe</th>
                  </tr>
                </thead>
                <tbody>
                  {dashboardData?.topSearches?.map((item, index) => (
                    <tr key={index}>
                      <td>{index + 1}</td>
                      <td>
                        <strong>{item.query}</strong>
                      </td>
                      <td>
                        <span className="badge bg-primary">{item.count}</span>
                      </td>
                      <td>
                        <span className={`badge bg-${item.type === 'vendor' ? 'success' : 'info'}`}>
                          {item.type}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </Table>
            </Card.Body>
          </Card>
        </Col>

        {/* Recent Activity */}
        <Col lg={6}>
          <Card className="h-100">
            <Card.Header className="bg-success text-white">
              <FaCalendarAlt className="me-2" /> Aktivitas Terkini
            </Card.Header>
            <Card.Body>
              <div className="activity-timeline">
                {dashboardData?.recentActivity?.map((activity, index) => (
                  <div key={index} className="activity-item">
                    <div className="activity-icon">
                      {activity.search_type === 'vendor' && <FaBuilding />}
                      {activity.search_type === 'package' && <FaDatabase />}
                      {activity.search_type === 'sbu' && <FaSearch />}
                    </div>
                    <div className="activity-content">
                      <div className="d-flex justify-content-between">
                        <strong>{activity.search_query}</strong>
                        <small className="text-muted">
                          {new Date(activity.timestamp).toLocaleTimeString('id-ID')}
                        </small>
                      </div>
                      <p className="mb-0 text-muted">
                        {activity.search_type} search
                      </p>
                    </div>
                  </div>
                ))}
              </div>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Monthly Trends - Simple Table instead of Chart */}
      <Row className="mt-4">
        <Col>
          <Card>
            <Card.Header className="bg-info text-white">
              <FaChartBar className="me-2" /> Tren Bulanan
            </Card.Header>
            <Card.Body>
              <Table hover responsive>
                <thead>
                  <tr>
                    <th>Bulan</th>
                    <th>Pencarian</th>
                    <th>Export</th>
                    <th>Growth</th>
                  </tr>
                </thead>
                <tbody>
                  {dashboardData?.monthlyTrends?.map((trend, index) => {
                    const growth = index > 0 
                      ? (((trend.searches - dashboardData.monthlyTrends[index-1].searches) / dashboardData.monthlyTrends[index-1].searches) * 100).toFixed(1)
                      : 0;
                    
                    return (
                      <tr key={index}>
                        <td><strong>{trend.month}</strong></td>
                        <td>
                          <div className="d-flex align-items-center">
                            <div className="progress flex-grow-1 me-2" style={{ height: '8px' }}>
                              <div 
                                className="progress-bar bg-primary" 
                                style={{ width: `${(trend.searches / 100) * 100}%` }}
                              ></div>
                            </div>
                            <span>{trend.searches}</span>
                          </div>
                        </td>
                        <td>
                          <span className="badge bg-success">{trend.exports}</span>
                        </td>
                        <td>
                          <span className={`badge ${growth >= 0 ? 'bg-success' : 'bg-danger'}`}>
                            {growth >= 0 ? '+' : ''}{growth}%
                          </span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </Table>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      <style jsx>{`
        .icon-circle {
          width: 50px;
          height: 50px;
          border-radius: 50%;
          display: flex;
          align-items: center;
          justify-content: center;
          color: white;
          font-size: 1.2rem;
        }
        
        .bg-primary { background: var(--gradient-primary); }
        .bg-success { background: var(--gradient-secondary); }
        .bg-info { background: linear-gradient(135deg, #0dcaf0 0%, #31d2f2 100%); }
        .bg-warning { background: linear-gradient(135deg, #ffc107 0%, #ffd54f 100%); }
        
        .activity-timeline {
          position: relative;
          padding-left: 30px;
        }
        
        .activity-timeline::before {
          content: '';
          position: absolute;
          left: 15px;
          top: 0;
          bottom: 0;
          width: 2px;
          background: var(--gray-light);
        }
        
        .activity-item {
          position: relative;
          margin-bottom: 1.5rem;
        }
        
        .activity-icon {
          position: absolute;
          left: -30px;
          width: 30px;
          height: 30px;
          border-radius: 50%;
          background: white;
          border: 2px solid var(--primary);
          display: flex;
          align-items: center;
          justify-content: center;
          color: var(--primary);
        }
        
        .activity-content {
          background: var(--gray-light);
          padding: 1rem;
          border-radius: 10px;
          border-left: 4px solid var(--primary);
        }
        
        .dark-mode .activity-content {
          background: #2d3748;
        }
        
        .dark-mode .activity-icon {
          background: #1a1d20;
          border-color: var(--primary-light);
          color: var(--primary-light);
        }
      `}</style>
    </Container>
  );
};

export default AdvancedDashboardPage;